def glass(mask, fill='#fff', opacity=.86, refraction=.09, specular='outside', shadow=.012):
    return layer(mask, fill, opacity, refraction, specular, shadow, 'glass', 'normal', (0, -2), 0, 1.2, 3.2)


def ink(mask, fill='#fff', opacity=1.0):
    return layer(mask, fill, opacity, 0, 'off', 0, 'ink', 'normal', (0, 0), 0, 0, 0)


def _gmail():
    # The Gmail mark is an M, not a generic envelope/card.
    left = stroked_path_mask('M264 350 L264 700', width=62)
    diag_l = stroked_path_mask('M264 350 L512 536', width=62)
    diag_r = stroked_path_mask('M512 536 L760 350', width=62)
    right = stroked_path_mask('M760 350 L760 700', width=62)
    return [
        glass(left, '#4285f4', .90, .075),
        glass(diag_l, '#ea4335', .92, .078),
        glass(diag_r, '#fbbc04', .90, .078),
        glass(right, '#34a853', .90, .075),
    ]


def _gamehub():
    # Current GameHub: two angular rails around a plus and two circular buttons.
    # Geometry follows the real mark rather than the previous made-up console body.
    left = stroked_path_mask('M370 244 L230 512 L370 676 L580 676', width=72, linecap='round', linejoin='round')
    right = stroked_path_mask('M442 304 L648 304 L794 512 L654 722', width=72, linecap='round', linejoin='round')
    plus_h = rounded_rect_mask(316, 466, 150, 58, 25)
    plus_v = rounded_rect_mask(362, 420, 58, 150, 25)
    dot1 = circle_mask(548, 496, 34)
    dot2 = circle_mask(646, 496, 34)
    return [glass(left, '#f8fafc', .90, .092), glass(right, '#f8fafc', .90, .092),
            glass(plus_h, '#f8fafc', .90, .088), glass(plus_v, '#f8fafc', .90, .088),
            glass(dot1, '#f8fafc', .90, .088), glass(dot2, '#f8fafc', .90, .088)]


def _kaspi():
    # White circular Kaspi emblem with two organic figures cut out of it.
    outer = circle_mask(512, 512, 296)
    figures = svg_mask('''
      <path d="M390 298 C354 294 331 327 340 366 C349 405 324 431 316 478 C306 533 329 568 324 612 L303 741 H382 L405 617 L428 741 H515 L505 595 C499 537 475 505 458 459 C450 437 453 414 468 400 C489 382 500 351 486 326 C469 298 430 286 390 298 Z" fill="#fff"/>
      <path d="M610 378 C574 379 551 408 560 444 C569 478 548 496 542 534 C535 578 553 606 548 642 L531 742 H599 L620 650 L640 742 H713 L700 621 C696 581 681 552 668 521 C659 500 664 481 680 466 C698 449 705 421 692 400 C678 377 644 368 610 378 Z" fill="#fff"/>
      <path d="M452 434 C498 458 536 469 575 454 L594 508 C536 531 482 520 429 486 Z" fill="#fff"/>
    ''')
    mark = ImageChops.subtract(outer, figures)
    return [glass(mark, '#ffffff', .90, .082, 'inside', .008)]


def _playstore():
    target = (188, 226, 836, 798)
    return [
        glass(path_mask(GOOGLE_PLAY_LEFT_D, viewbox=(0, 0, 24, 24), target=target), '#34a853', .90, .080),
        glass(path_mask(GOOGLE_PLAY_TOP_D, viewbox=(0, 0, 24, 24), target=target), '#fbbc04', .90, .080),
        glass(path_mask(GOOGLE_PLAY_BOTTOM_D, viewbox=(0, 0, 24, 24), target=target), '#ea4335', .90, .080),
        glass(path_mask(GOOGLE_PLAY_TIP_D, viewbox=(0, 0, 24, 24), target=target), '#4285f4', .90, .080),
    ]


def glyph_brand_curated(kind):
    if kind not in BRAND_CURATED_KINDS:
        return None

    if kind == 'gmail':
        return _gmail()
    if kind == 'gamehub':
        return _gamehub()
    if kind == 'kaspi':
        return _kaspi()
    if kind == 'playstore':
        return _playstore()

    if kind == 'telegram':
        # Optical center moved right ~18 units; previous mathematically centered
        # target looked left-heavy because the paper plane has an asymmetric mass.
        from .glyphs_vector import TELEGRAM_PLANE_D
        m = path_mask(TELEGRAM_PLANE_D, viewbox=(112, 157, 258, 218), target=(202, 222, 858, 812))
        return [glass(m, '#ffffff', .90, .100)]

    table = {
        'github': (GITHUB_D, (176, 166, 848, 842), '#f7f8fa', .88),
        'pinterest': (PINTEREST_D, (188, 170, 836, 850), '#ffffff', .90),
        'facebook': (FACEBOOK_D, (190, 170, 834, 850), '#ffffff', .90),
        'reddit': (REDDIT_D, (184, 172, 840, 842), '#ffffff', .90),
        'tiktok': (TIKTOK_D, (214, 164, 810, 848), '#f7f8fa', .88),
        'whatsapp': (WHATSAPP_D, (184, 166, 840, 850), '#ffffff', .90),
        'twitter': (X_D, (216, 186, 808, 838), '#ffffff', .90),
        'steam': (STEAM_D, (180, 166, 844, 846), '#f5f7fa', .88),
        'snapchat': (SNAPCHAT_D, (190, 166, 834, 846), '#17181c', .98),
    }
    d, target, fill, opacity = table[kind]
    m = path_mask(d, viewbox=(0, 0, 24, 24), target=target, fill_rule='evenodd')
    if kind == 'snapchat':
        return [ink(m, fill, opacity)]
    return [glass(m, fill, opacity, .090)]
